/**
 * Generated-file marker.
 *
 * Every file the Pi generator writes into prompts/, agents/ or skills/ carries the same HTML
 * comment, as its first line or (for a file with YAML frontmatter) as the first line after the
 * frontmatter:
 *
 *   <!-- Generated by ensemble-pi generator v1.0.0 | Source: <what it was generated from> -->
 *
 * The marker is the generator's proof of authorship. Pruning (generator.ts) removes a file the
 * current run did not reproduce only when it can prove the generator wrote it, so a hand-authored
 * file in the same directory is never touched. The writers (command, agent and skill transformers)
 * and the recognizer share this one definition; command-wrapper skills carry their own marker (see
 * command-skill-transformer.ts), which is the only other proof pruning accepts.
 *
 * @module ensemble-pi/generated-marker
 */

/** What every marker starts with. Recognition keys on this prefix, never on the version or source. */
export const GENERATED_MARKER_PREFIX = '<!-- Generated by ensemble-pi generator';

/** The marker comment for a file generated from `source` (a file name or a repo-relative path). */
export function generatedMarker(source: string): string {
  return `${GENERATED_MARKER_PREFIX} v1.0.0 | Source: ${source} -->`;
}

/**
 * Second line of a command prompt's header. A command-wrapper skill is the prompt body minus the
 * first header line, so it keeps this line, and it is what ties a wrapper to the command it was
 * generated from (see isCommandWrapperSkill).
 */
export const COMMAND_HEADER_PREFIX = '<!-- Command: ';

/** The `Command:` header line of a prompt for command `name` at `version`. */
export function commandHeaderLine(name: string, version: string): string {
  return `${COMMAND_HEADER_PREFIX}${name} | Version: ${version} -->`;
}

/**
 * What an Agent Skills `name`, and so a skill directory, may be: lowercase letters, digits and
 * single hyphens, at most 64 characters. isValidSkillName mirrors scripts/lib/skill-backed-command.js,
 * which the Claude, Codex and OpenCode generators use and this standalone package cannot import.
 */
const SKILL_NAME_CORE = '[a-z0-9]+(?:-[a-z0-9]+)*';
const SKILL_NAME = new RegExp(`^${SKILL_NAME_CORE}$`);
const SKILL_NAME_MAX_LENGTH = 64;

export function isValidSkillName(name: unknown): name is string {
  return typeof name === 'string' && name.length <= SKILL_NAME_MAX_LENGTH && SKILL_NAME.test(name);
}

/**
 * Third line of the prompt header of a skill-backed command, a command whose YAML is a manifest
 * naming the skill that carries its whole prompt (CommandYaml.skill). The prompt of such a command
 * is a stub that points the agent at that skill, and the skill is shipped as it is (skill-copier,
 * or in place in a self-contained package), so it is the command's one skill: no command-wrapper
 * skill is generated for the stub (generateCommandSkills), which would otherwise land on the very
 * path of the skill whenever that is named `ensemble-<cmd>`.
 */
export const SKILL_HEADER_PREFIX = '<!-- Skill: ';

/** The `Skill:` header line of the stub prompt of a command backed by skill `skill`. */
export function skillHeaderLine(skill: string): string {
  return `${SKILL_HEADER_PREFIX}${skill} -->`;
}

function escapeRegExp(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * The generated header a skill-backed command's prompt opens with: the marker line, the `Command:`
 * line, then the `Skill:` line (its skill name captured). Strict like isCommandWrapperSkill: a
 * hand-authored prompt, or one that merely quotes such a line deeper in its text, does not match.
 */
const SKILL_BACKED_PROMPT_HEADER = new RegExp(
  `^${escapeRegExp(GENERATED_MARKER_PREFIX)}[^\\r\\n]*-->\\r?\\n` +
    `${escapeRegExp(COMMAND_HEADER_PREFIX)}[^\\r\\n]*-->\\r?\\n` +
    `${escapeRegExp(SKILL_HEADER_PREFIX)}(${SKILL_NAME_CORE}) -->(?:\\r?\\n|$)`
);

/** The skill a generated prompt is the stub of, or undefined when it is not a skill-backed command's. */
export function skillOfPrompt(content: string): string | undefined {
  return SKILL_BACKED_PROMPT_HEADER.exec(content)?.[1];
}

/**
 * Leading YAML frontmatter block: `---`, optional lines, `---`. Matches the delimiters only, with
 * no YAML parsing, so a hand-authored file with malformed frontmatter can still be inspected
 * (and is then simply not recognised as generated).
 */
const FRONTMATTER = /^\uFEFF?---[ \t]*\r?\n(?:[\s\S]*?\r?\n)?---[ \t]*(?:\r?\n|$)/;

/**
 * Whether the generator wrote this file: its first non-blank line after the optional frontmatter
 * is a generated marker. A marker quoted deeper in a hand-authored document does not count.
 */
export function hasGeneratedMarker(content: string): boolean {
  const body = content.slice(FRONTMATTER.exec(content)?.[0].length ?? 0);
  return body.trimStart().startsWith(GENERATED_MARKER_PREFIX);
}

/**
 * `content` with the generated marker for `source` inserted as its first line, or as the first
 * line after the frontmatter when it has one. Nothing else in the content changes.
 */
export function withGeneratedMarker(content: string, source: string): string {
  const at = FRONTMATTER.exec(content)?.[0].length ?? 0;
  return `${content.slice(0, at)}${generatedMarker(source)}\n${content.slice(at)}`;
}
